// Bundles src/client-entry.tsx into a self-contained browser IIFE and writes it as a
// base64 TS constant in src/vendor/client-bundle.ts, so renderer.tsx can inline it into
// the generated HTML without depending on a runtime filesystem path (see prism-theme.ts /
// bootstrap-icons-font.ts for the same pattern). Must run before `tsc`.
import esbuild from "esbuild";
import { writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(__dirname, "..");

const result = await esbuild.build({
  entryPoints: [path.join(root, "src/client-entry.tsx")],
  bundle: true,
  minify: true,
  format: "iife",
  platform: "browser",
  target: "es2020",
  jsx: "automatic",
  jsxImportSource: "react",
  // AstRenderer.tsx is pulled in from ../../renderer/components, which has its own
  // node_modules/react — without forcing resolution to mcp-server's copy, the bundle ends
  // up with two React instances and hooks crash with "Cannot read properties of null
  // (reading 'useState')" (null dispatcher) the moment a hook runs client-side.
  alias: {
    react: path.join(root, "node_modules/react"),
    "react-dom": path.join(root, "node_modules/react-dom"),
    "react/jsx-runtime": path.join(root, "node_modules/react/jsx-runtime"),
    "react-dom/client": path.join(root, "node_modules/react-dom/client"),
  },
  define: {
    // AstRenderer.tsx pulls these in transitively via lib/api.ts; `process` doesn't exist
    // in a browser, so leaving them unreplaced throws ReferenceError before hydration runs.
    // Values mirror lib/api.ts's own fallback defaults (the harness's local dev backend).
    "process.env.NODE_ENV": '"production"',
    "process.env.NEXT_PUBLIC_DATA_URL": '"http://localhost:4000/data"',
    "process.env.NEXT_PUBLIC_API_URL": '"http://localhost:4000/api"',
  },
  write: false,
});

const js = result.outputFiles[0].text;
const base64 = Buffer.from(js, "utf-8").toString("base64");

const outPath = path.join(root, "src/vendor/client-bundle.ts");
writeFileSync(
  outPath,
  `// Auto-generated by scripts/build-client-bundle.mjs — do not edit directly.\nexport const CLIENT_BUNDLE_JS_BASE64 = "${base64}";\n`,
);

console.log(`Wrote ${outPath} (${(js.length / 1024).toFixed(1)} KB minified client bundle)`);
